class CalendarUtil {

    let events: ArrayList<Event>

    public init() {
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        this.events.remove(event)
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        let result = ArrayList<Event>()
        for evt in this.events {
            if evt.date == date {
                result.add(evt)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        for evt in this.events {
            if (start_time >= evt.start_time && start_time < evt.end_time) ||
               (end_time > evt.start_time && end_time <= evt.end_time) ||
               (start_time <= evt.start_time && end_time >= evt.end_time) {
                return false
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        let slots = ArrayList<(DateTime, DateTime)>()
        let current_time = DateTime.of(
            year: date.year,
            month: date.month,
            dayOfMonth: date.dayOfMonth,
            hour: 0,
            minute: 0
        )
        let day_end = DateTime.of(
            year: date.year,
            month: date.month,
            dayOfMonth: date.dayOfMonth,
            hour: 23,
            minute: 59
        )

        let day_events = this.get_events(date)
        day_events.sort(|a, b| -> Int64 { a.start_time <=> b.start_time })

        var prev_end = current_time
        for evt in day_events {
            if evt.start_time > prev_end {
                slots.add((prev_end, evt.start_time))
            }
            prev_end = evt.end_time
        }

        if prev_end < day_end {
            slots.add((prev_end, day_end))
        }

        return slots
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        let now = DateTime.now()
        let upcoming = ArrayList<Event>()
        let sorted_events = this.events.clone()
        sorted_events.sort(|a, b| -> Int64 { a.date <=> b.date })

        var count: Int64 = 0
        for evt in sorted_events {
            if evt.date >= now {
                upcoming.add(evt)
                count += 1
                if count >= num_events {
                    break
                }
            }
        }
        return upcoming
    }
}

import std.collection.HashMap

class CamelCaseMap {

    let _data: HashMap<String, Any>

    public init() {
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        let camelKey = _convert_key(key) as String
        return _data[camelKey] ?? None
    }

    public func __setitem__(key: String, value: Any): Unit {
        let camelKey = _convert_key(key) as String
        _data[camelKey] = value
    }

    public func __delitem__(key: String): Unit {
        let camelKey = _convert_key(key) as String
        _data.remove(camelKey)
    }

    public func __len__(): Int64 {
        return _data.size()
    }

    public func _convert_key(key: Any): Any {
        if key is String {
            return CamelCaseMap._to_camel_case(key as String)
        }
        return key
    }

    public static func _to_camel_case(key: String): String {
        let parts = key.split('_')
        if parts.size() == 0 {
            return ""
        }
        let camelCase = parts[0]
        for i in 1..parts.size() {
            let part = parts[i]
            if part.size() > 0 {
                camelCase += part[0].upper() + part[1..]
            }
        }
        return camelCase
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        if n < 2 {
            return ArrayList<Int64>()
        }

        var sieve = ArrayList<Boolean>(size: n + 1, default: true)
        sieve[0] = false
        sieve[1] = false

        for i in 2..n + 1 {
            if sieve[i] {
                primes.add(i)
                for j in i * i..n + 1 step i {
                    sieve[j] = false
                }
            }
        }

        return primes
    }

    public func get_primes(): ArrayList<Int64> {
        return this.primes
    }
}

