class ClassRegistrationSystem {

    var students: ArrayList<HashMap<String, String>>
    var students_registration_classes: HashMap<String, ArrayList<String>>

    public init() {
        this.students = ArrayList<HashMap<String, String>>()
        this.students_registration_classes = HashMap<String, ArrayList<String>>()
    }

    public func register_student(student: HashMap<String, String>): Int64 {
        for s in this.students {
            if s.get("name") == student.get("name") {
                return 0
            }
        }
        this.students.add(student)
        return 1
    }

    public func register_class(student_name: String, class_name: String): ArrayList<String> {
        if !this.students_registration_classes.contains(student_name) {
            this.students_registration_classes.put(student_name, ArrayList<String>())
        }
        var classes = this.students_registration_classes.get(student_name)
        classes.add(class_name)
        return classes
    }

    public func get_students_by_major(major: String): ArrayList<String> {
        var result = ArrayList<String>()
        for student in this.students {
            if student.get("major") == major {
                result.add(student.get("name"))
            }
        }
        return result
    }

    public func get_all_major(): ArrayList<String> {
        var majors = ArrayList<String>()
        for student in this.students {
            var major = student.get("major")
            if !majors.contains(major) {
                majors.add(major)
            }
        }
        return majors
    }

    public func get_most_popular_class_in_major(major: String): String {
        var class_count = HashMap<String, Int64>()
        var students_in_major = get_students_by_major(major)

        for student in students_in_major {
            if this.students_registration_classes.contains(student) {
                var classes = this.students_registration_classes.get(student)
                for class_name in classes {
                    var count = class_count.get_or_default(class_name, 0)
                    class_count.put(class_name, count + 1)
                }
            }
        }

        var max_count: Int64 = 0
        var popular_class = ""
        for (class_name, count) in class_count {
            if count > max_count {
                max_count = count
                popular_class = class_name
            }
        }
        return popular_class
    }
}

import std.collection.ArrayList

class CombinationCalculator {

    let datas: ArrayList<String>

    public init(datas: ArrayList<String>) {
        this.datas = datas
    }

    public static func factorial(n: Int64): Int64 {
        var result: Int64 = 1
        for (i in 1..n + 1) {
            result *= i
        }
        return result
    }

    public static func count(n: Int64, m: Int64): Int64 {
        if (m > n) {
            return 0
        }
        return CombinationCalculator.factorial(n) / (CombinationCalculator.factorial(m) * CombinationCalculator.factorial(n - m))
    }

    public static func count_all(n: Int64): Int64 {
        var result: Int64 = 0
        for (i in 1..n + 1) {
            result += CombinationCalculator.count(n, i)
        }
        return result
    }

    public func select(m: Int64): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        this._select(0, ArrayList<String>(Array<String>(m.toInt(), repeat: "")), 0, result)
        return result
    }

    public func select_all(): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        for (i in 1..this.datas.size() + 1) {
            result.addAll(this.select(i))
        }
        return result
    }

    public func _select(dataIndex: Int64, resultList: ArrayList<String>, resultIndex: Int64, result: ArrayList<ArrayList<String>>): Unit {
        if (resultIndex == resultList.size()) {
            result.add(ArrayList<String>(resultList))
            return
        }
        if (dataIndex == this.datas.size()) {
            return
        }
        resultList.set(resultIndex, this.datas.get(dataIndex))
        this._select(dataIndex + 1, resultList, resultIndex + 1, result)
        this._select(dataIndex + 1, resultList, resultIndex, result)
    }
}

import std.math.abs

class ComplexNumber <: Equatable<ComplexNumber> {

    public var real: Float64
    public var imaginary: Float64

    public init(real: Float64, imaginary: Float64) {
        this.real = real
        this.imaginary = imaginary
    }

    public override operator func != (that: ComplexNumber): Bool {
        return this.real != that.real || this.imaginary != that.imaginary
    }

    public override operator func == (that: ComplexNumber): Bool {
        return this.real == that.real && this.imaginary == that.imaginary
    }
}


class ComplexCalculator {

    public init() { }

    public static func add(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        return ComplexNumber(real: c1.real + c2.real, imaginary: c1.imaginary + c2.imaginary)
    }

    public static func subtract(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        return ComplexNumber(real: c1.real - c2.real, imaginary: c1.imaginary - c2.imaginary)
    }

    public static func multiply(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let real = c1.real * c2.real - c1.imaginary * c2.imaginary
        let imaginary = c1.real * c2.imaginary + c1.imaginary * c2.real
        return ComplexNumber(real: real, imaginary: imaginary)
    }

    public static func divide(c1: ComplexNumber, c2: ComplexNumber): ComplexNumber {
        let denominator = c2.real * c2.real + c2.imaginary * c2.imaginary
        let real = (c1.real * c2.real + c1.imaginary * c2.imaginary) / denominator
        let imaginary = (c1.imaginary * c2.real - c1.real * c2.imaginary) / denominator
        return ComplexNumber(real: real, imaginary: imaginary)
    }
}

import std.collection.ArrayList
import std.fs.*
import std.io.*
import std.unicode.UnicodeStringExtension

class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let title = ArrayList<String>()
        let data = ArrayList<ArrayList<String>>()
        let file = File(file_name)
        if !file.exists() {
            return (title, data)
        }
        let reader = FileReader(file_name)
        var is_first_line = true
        while let line = reader.readLine() {
            let row = line.split(',')
            if is_first_line {
                is_first_line = false
                for item in row {
                    title.add(item.trim())
                }
            } else {
                let row_data = ArrayList<String>()
                for item in row {
                    row_data.add(item.trim())
                }
                data.add(row_data)
            }
        }
        reader.close()
        return (title, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file = File(file_name)
        let writer = FileWriter(file_name)
        for row in data {
            let line = row.join(',')
            writer.writeLine(line)
        }
        writer.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (title, data) = read_csv(save_file_name)
        let new_data = ArrayList<ArrayList<String>>()
        for row in data {
            if N >= 0 && N < row.size() {
                let new_row = ArrayList<String>()
                new_row.add(row[N].toUpperCase())
                new_data.add(new_row)
            }
        }
        let new_file_name = save_file_name.replace(".csv", "") + "_process.csv"
        let merged_data = ArrayList<ArrayList<String>>()
        merged_data.add(title)
        merged_data.addAll(new_data)
        return write_csv(merged_data, new_file_name)
    }
}

