class DataStatistics {

    public func mean(data: ArrayList<Int64>): Float64 {
        let sum = data.reduce(0, fn(acc, x) => acc + x)
        let mean = Float64(sum) / Float64(data.size())
        return round(mean * 100) / 100
    }

    public func median(data: ArrayList<Int64>): Float64 {
        let sorted = sort(data)
        let size = sorted.size()
        if size % 2 == 1 {
            return Float64(sorted[size // 2])
        } else {
            let mid1 = sorted[size // 2 - 1]
            let mid2 = sorted[size // 2]
            return round(Float64(mid1 + mid2) / 2.0 * 100) / 100
        }
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let freq = HashMap<Int64, Int64>()
        for num in data {
            freq.put(num, freq.getOrDefault(num, 0) + 1)
        }

        let maxFreq = freq.values().reduce(0, fn(acc, x) => if x > acc then x else acc)
        let modes = ArrayList<Int64>()
        for entry in freq.entries() {
            if entry.value == maxFreq {
                modes.add(entry.key)
            }
        }
        return sort(modes)
    }
}

import std.collection.ArrayList
import std.math.round
import std.math.sqrt
import std.math.abs

class DataStatistics2 {

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        this.data = data
    }

    public func get_sum(): Float64 {
        let sum: Float64 = 0.0
        for num in this.data {
            sum += num
        }
        return sum
    }

    public func get_min(): Float64 {
        let min_val: Float64 = this.data[0]
        for num in this.data {
            if num < min_val {
                min_val = num
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        let max_val: Float64 = this.data[0]
        for num in this.data {
            if num > max_val {
                max_val = num
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        let mean: Float64 = this.get_sum() / this.data.size().to_float64()
        let variance: Float64 = 0.0
        for num in this.data {
            variance += (num - mean) * (num - mean)
        }
        variance /= this.data.size().to_float64()
        return round(variance * 100) / 100
    }

    public func get_std_deviation(): Float64 {
        let std_dev: Float64 = sqrt(this.get_variance())
        return round(std_dev * 100) / 100
    }

    public func get_correlation(): Float64 {
        let n: Int = this.data.size()
        let sum_x: Float64 = this.get_sum()
        let sum_y: Float64 = sum_x
        let sum_xy: Float64 = 0.0
        let sum_x2: Float64 = 0.0
        let sum_y2: Float64 = 0.0

        for i in 0..n {
            let x: Float64 = this.data[i]
            let y: Float64 = this.data[i]
            sum_xy += x * y
            sum_x2 += x * x
            sum_y2 += y * y
        }

        let numerator: Float64 = sum_xy - (sum_x * sum_y / n.to_float64())
        let denominator: Float64 = sqrt((sum_x2 - (sum_x * sum_x / n.to_float64())) * (sum_y2 - (sum_y * sum_y / n.to_float64())))
        return round(numerator / denominator * 100) / 100
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs
import std.math.pow

class DataStatistics4 {

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        let n = data1.size()
        let sum1 = data1.sum()
        let sum2 = data2.sum()
        let sum1_sq = data1.map(|x| x * x).sum()
        let sum2_sq = data2.map(|x| x * x).sum()
        let p_sum = data1.zip(data2).map(|(x, y)| x * y).sum()
        let numerator = p_sum - (sum1 * sum2 / n)
        let denominator = sqrt((sum1_sq - sum1 * sum1 / n) * (sum2_sq - sum2 * sum2 / n))
        return numerator / denominator
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / n
        let variance = data.map(|x| pow(x - mean, 2)).sum() / n
        let std_dev = sqrt(variance)
        let skew = data.map(|x| pow((x - mean) / std_dev, 3)).sum() / n
        return skew
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        let n = data.size()
        let mean = data.sum() / n
        let variance = data.map(|x| pow(x - mean, 2)).sum() / n
        let kurt = data.map(|x| pow((x - mean) / sqrt(variance), 4)).sum() / n - 3.0
        return kurt
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        let coeff = 1.0 / (sigma * sqrt(2.0 * 3.141592653589793))
        return data.map(|x| {
            let exponent = -0.5 * pow((x - mu) / sigma, 2)
            coeff * exp(exponent)
        })
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        let result = ArrayList<Char>()
        for c in ciphertext {
            if c.is_alpha() {
                let base = c.is_lower() ? 'a' : 'A'
                let shifted = (c - base - shift) % 26
                result.push(base + shifted + (if shifted < 0 then 26 else 0))
            } else {
                result.push(c)
            }
        }
        return result.join("")
    }

    public func vigenere_decipher(ciphertext: String): String {
        let result = ArrayList<Char>()
        let key_chars = this.key.to_lower().chars()
        let key_len = key_chars.size()
        var key_idx = 0
        for c in ciphertext {
            if c.is_alpha() {
                let base = c.is_lower() ? 'a' : 'A'
                let key_c = key_chars[key_idx % key_len]
                let shift = key_c - 'a'
                let shifted = (c - base - shift) % 26
                result.push(base + shifted + (if shifted < 0 then 26 else 0))
                key_idx += 1
            } else {
                result.push(c)
            }
        }
        return result.join("")
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        let len = encrypted_text.length()
        let decoded = ArrayList<Char>(len)
        for _ in 0..len {
            decoded.push(' ')
        }
        var idx = 0
        for rail in 0..rails {
            let cycle_len = 2 * (rails - 1)
            for i in rail..len step cycle_len {
                decoded[i] = encrypted_text[idx]
                idx += 1
                if rail != 0 && rail != rails - 1 {
                    let next_i = i + cycle_len - 2 * rail
                    if next_i < len {
                        decoded[next_i] = encrypted_text[idx]
                        idx += 1
                    }
                }
            }
        }
        return decoded.join("")
    }
}

