import std.collection.ArrayList

class EightPuzzle {

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        for i in 0..<state.size() {
            for j in 0..<state[i].size() {
                if state[i][j] == 0 {
                    return (i, j)
                }
            }
        }
        return (-1, -1)
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        let new_state = ArrayList<ArrayList<Int64>>()
        for row in state {
            new_state.append(ArrayList<Int64>(row))
        }
        let (i, j) = find_blank(state: new_state)

        if direction == "up" && i > 0 {
            new_state[i][j] = new_state[i-1][j]
            new_state[i-1][j] = 0
        } else if direction == "down" && i < new_state.size()-1 {
            new_state[i][j] = new_state[i+1][j]
            new_state[i+1][j] = 0
        } else if direction == "left" && j > 0 {
            new_state[i][j] = new_state[i][j-1]
            new_state[i][j-1] = 0
        } else if direction == "right" && j < new_state[i].size()-1 {
            new_state[i][j] = new_state[i][j+1]
            new_state[i][j+1] = 0
        }

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        let moves = ArrayList<String>()
        let (i, j) = find_blank(state: state)

        if i > 0 {
            moves.append("up")
        }
        if i < state.size()-1 {
            moves.append("down")
        }
        if j > 0 {
            moves.append("left")
        }
        if j < state[i].size()-1 {
            moves.append("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        let open_list = ArrayList<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        let closed_list = ArrayList<ArrayList<ArrayList<Int64>>>()

        open_list.append((this.initial_state, ArrayList<String>()))

        while open_list.size() > 0 {
            let (current_state, path) = open_list.remove(0)

            if current_state == this.goal_state {
                return path
            }

            if !closed_list.contains(current_state) {
                closed_list.append(current_state)

                let possible_moves = get_possible_moves(state: current_state)
                for move in possible_moves {
                    let new_state = move(state: current_state, direction: move)
                    let new_path = ArrayList<String>(path)
                    new_path.append(move)
                    open_list.append((new_state, new_path))
                }
            }
        }

        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        if recv.is_full_with_one_more_email(size) {
            return false
        }
        let email = HashMap<String, Any>()
        email.put("sender", this.addr)
        email.put("receiver", recv.addr)
        email.put("content", content)
        email.put("size", size)
        email.put("time", DateTime.now())
        email.put("state", "unread")
        recv.inbox.add(email)
        return true
    }

    public func fetch(): HashMap<String, Any> {
        for email in this.inbox {
            if email.get("state") == "unread" {
                email.put("state", "read")
                return email
            }
        }
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        return this.get_occupied_size() + size > this.capacity
    }

    public func get_occupied_size(): Int64 {
        var total: Int64 = 0
        for email in this.inbox {
            total += email.get("size") as Int64
        }
        return total
    }

    public func clear_inbox(size: Int64): Unit {
        while this.is_full_with_one_more_email(size) and not this.inbox.is_empty() {
            this.inbox.remove_at(0)
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    let key: String

    public init(key: String) {
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        let ciphertext = ArrayList<Character>()
        for c in plaintext {
            let base = c.is_uppercase() ? 'A'.to_int() : 'a'.to_int()
            let shifted = (c.to_int() - base + shift) % 26 + base
            ciphertext.add(shifted.to_char())
        }
        return ciphertext.join("")
    }

    public func vigenere_cipher(plain_text: String): String {
        let ciphertext = ArrayList<Character>()
        let key_chars = this.key.to_lower().chars()
        let key_length = key_chars.size()
        let mut i = 0
        for c in plain_text {
            let base = c.is_uppercase() ? 'A'.to_int() : 'a'.to_int()
            let key_shift = key_chars[i % key_length].to_int() - 'a'.to_int()
            let shifted = (c.to_int() - base + key_shift) % 26 + base
            ciphertext.add(shifted.to_char())
            i += 1
        }
        return ciphertext.join("")
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        if rails == 1 {
            return plain_text
        }
        let rail_strings = ArrayList<String>(rails)
        for _ in 0..rails {
            rail_strings.add("")
        }
        let mut rail = 0
        let mut direction = 1
        for c in plain_text {
            rail_strings[rail] += c.to_string()
            rail += direction
            if rail == 0 || rail == rails - 1 {
                direction *= -1
            }
        }
        return rail_strings.join("")
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        prepare(expression)
        let temp_stack = ArrayList<Decimal>()
        for c in postfix_stack {
            if !is_operator(c) {
                temp_stack.add(Decimal(c))
            } else {
                let second_value = temp_stack.remove(temp_stack.size() - 1)
                let first_value = temp_stack.remove(temp_stack.size() - 1)
                let result = _calculate(first_value, second_value, c)
                temp_stack.add(result)
            }
        }
        return temp_stack.get(0).to_float64()
    }

    public func prepare(expression: String): Unit {
        postfix_stack.clear()
        let transformed = ExpressionCalculator.transform(expression)
        let op_stack = ArrayList<String>()
        let regex = Regex("[0-9]+(\\.[0-9]+)?")
        let tokens = regex.split(transformed)
        for token in tokens {
            if token.is_empty() {
                continue
            }
            if ExpressionCalculator.is_operator(token) {
                while !op_stack.is_empty() && 
                      token != "(" && 
                      compare(op_stack.get(op_stack.size() - 1), token) {
                    postfix_stack.add(op_stack.remove(op_stack.size() - 1))
                }
                if token == ")" {
                    op_stack.remove(op_stack.size() - 1)
                } else {
                    op_stack.add(token)
                }
            } else {
                postfix_stack.add(token)
            }
        }
        while !op_stack.is_empty() {
            postfix_stack.add(op_stack.remove(op_stack.size() - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        return ["+", "-", "*", "/", "(", ")", "%"].contains(c)
    }

    public func compare(cur: String, peek: String): Bool {
        let cur_idx = ["(", "+", "-", "*", "/", ")", "%"].index_of(cur)
        let peek_idx = ["(", "+", "-", "*", "/", ")", "%"].index_of(peek)
        return operat_priority.get(cur_idx) >= operat_priority.get(peek_idx)
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        match current_op {
            "+" => return first_value + second_value
            "-" => return first_value - second_value
            "*" => return first_value * second_value
            "/" => return first_value / second_value
            "%" => return first_value % second_value
            _ => return Decimal(0)
        }
    }

    public static func transform(expression: String): String {
        return expression.replace(" ", "")
    }
}

