import std.collection.ArrayList

class GomokuGame {

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if (row < 0 || row >= board_size || col < 0 || col >= board_size || board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        current_player = (current_player == "X") ? "O" : "X"
        return true
    }

    public func check_winner(): Option<String> {
        for (let i = 0; i < board_size; i++) {
            for (let j = 0; j < board_size; j++) {
                if (board[i][j] != " ") {
                    let directions = [(0, 1), (1, 0), (1, 1), (1, -1)]
                    for (dir in directions) {
                        if (_check_five_in_a_row(i, j, dir)) {
                            return Option.Some(board[i][j])
                        }
                    }
                }
            }
        }
        return Option.None<String>()
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        let (dx, dy) = direction
        let symbol = board[row][col]
        var count = 1
        var x = row + dx
        var y = col + dy
        while (x >= 0 && x < board_size && y >= 0 && y < board_size && board[x][y] == symbol) {
            count += 1
            x += dx
            y += dy
        }
        x = row - dx
        y = col - dy
        while (x >= 0 && x < board_size && y >= 0 && y < board_size && board[x][y] == symbol) {
            count += 1
            x -= dx
            y -= dy
        }
        return count >= 5
    }
}

import std.collection.HashMap

class Hotel {

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        if !this.available_rooms.containsKey(room_type) {
            return "false"
        }
        let available = this.available_rooms.get(room_type)
        if available <= 0 {
            return "false"
        }
        if room_number <= 0 {
            return "false"
        }
        if room_number > available {
            return available.toString()
        }
        this.available_rooms.put(room_type, available - room_number)
        if !this.booked_rooms.containsKey(room_type) {
            this.booked_rooms.put(room_type, HashMap<String, Int64>())
        }
        let guest_bookings = this.booked_rooms.get(room_type)
        if guest_bookings.containsKey(name) {
            guest_bookings.put(name, guest_bookings.get(name) + room_number)
        } else {
            guest_bookings.put(name, room_number)
        }
        return "Success!"
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        if !this.booked_rooms.containsKey(room_type) {
            return false
        }
        let guest_bookings = this.booked_rooms.get(room_type)
        if !guest_bookings.containsKey(name) {
            return false
        }
        let booked_number = guest_bookings.get(name)
        if booked_number < room_number {
            return false
        }
        if booked_number == room_number {
            guest_bookings.remove(name)
        } else {
            guest_bookings.put(name, booked_number - room_number)
        }
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        if this.available_rooms.containsKey(room_type) {
            this.available_rooms.put(room_type, this.available_rooms.get(room_type) + room_number)
        } else {
            this.available_rooms.put(room_type, room_number)
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        if !this.available_rooms.containsKey(room_type) {
            return 0
        }
        return this.available_rooms.get(room_type)
    }
}

