import std.collection.ArrayList

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for xi in x_interp {
            var i = 0
            while i < x.size() - 1 && x[i + 1] < xi {
                i += 1
            }
            if i == x.size() - 1 {
                result.add(y[y.size() - 1])
            } else {
                let x0 = x[i]
                let x1 = x[i + 1]
                let y0 = y[i]
                let y1 = y[i + 1]
                let yi = y0 + (y1 - y0) * (xi - x0) / (x1 - x0)
                result.add(yi)
            }
        }
        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        for i in 0..<x_interp.size() {
            let xi = x_interp[i]
            let yi = y_interp[i]

            var x_low = 0
            while x_low < x.size() - 1 && x[x_low + 1] < xi {
                x_low += 1
            }

            var y_low = 0
            while y_low < y.size() - 1 && y[y_low + 1] < yi {
                y_low += 1
            }

            let x_high = x_low + 1
            let y_high = y_low + 1

            let x0 = x[x_low]
            let x1 = x[x_high]
            let y0 = y[y_low]
            let y1 = y[y_high]

            let z00 = z[x_low][y_low]
            let z01 = z[x_low][y_high]
            let z10 = z[x_high][y_low]
            let z11 = z[x_high][y_high]

            let z0 = z00 + (z10 - z00) * (xi - x0) / (x1 - x0)
            let z1 = z01 + (z11 - z01) * (xi - x0) / (x1 - x0)
            let zi = z0 + (z1 - z0) * (yi - y0) / (y1 - y0)

            result.add(zi)
        }
        return result
    }
}

