class IPAddress {

    let ip_address: String

    public init(ip_address: String) {
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        let parts = ip_address.split(".")
        if parts.size() != 4 {
            return false
        }
        for part in parts {
            if !part.is_digit() {
                return false
            }
            let num = part.to_int()
            if num < 0 || num > 255 {
                return false
            }
        }
        return true
    }

    public func get_octets(): ArrayList<String> {
        let octets = ArrayList<String>()
        if !is_valid() {
            return octets
        }
        octets.add_all(ip_address.split("."))
        return octets
    }

    public func get_binary(): String {
        if !is_valid() {
            return ""
        }
        let octets = get_octets()
        let binary_parts = ArrayList<String>()
        for octet in octets {
            let num = octet.to_int()
            let binary = num.to_binary(8)
            binary_parts.add(binary)
        }
        return binary_parts.join(".")
    }
}

