import std.math.abs

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        var pe: Float64 = 0.0
        var po: Float64 = 0.0
        var total: Int64 = 0

        for i in 0..k {
            var rowSum: Int64 = 0
            var colSum: Int64 = 0
            for j in 0..k {
                rowSum += testData[i][j]
                colSum += testData[j][i]
            }
            po += testData[i][i]
            pe += rowSum * colSum
            total += rowSum
        }

        po = po / total.toFloat64()
        pe = pe / (total * total).toFloat64()

        if pe == 1.0 {
            return 1.0
        }

        return (po - pe) / (1.0 - pe)
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64,limit n: Int64): Float64 {
        var total: Int64 = N * n
        var p: ArrayList<Float64> = ArrayList<Float64>()
        var P: ArrayList<Float64> = ArrayList<Float64>()

        for j in 0..k {
            var sum: Int64 = 0
            for i in 0..N {
                sum += testData[i][j]
            }
            p.add(sum.toFloat64() / total.toFloat64())
        }

        var pe: Float64 = 0.0
        for j in 0..k {
            pe += p[j] * p[j]
        }

        for i in 0..N {
            var sum: Int64 = 0
            for j in 0..k {
                sum += testData[i][j] * testData[i][j]
            }
            P.add((sum - n).toFloat64() / (n * (n - 1)).toFloat64())
        }

        var po: Float64 = 0.0
        for i in 0..N {
            po += P[i]
        }
        po = po / N.toFloat64()

        if pe == 1.0 {
            return 1.0
        }

        return (po - pe) / (1.0 - pe)
    }
}

