import std.collection.ArrayList
import std.collection.HashSet
import std.random.Random

class MahjongConnect {

    let BOARD_SIZE: ArrayList<Int64>
    let ICONS: ArrayList<String>
    var board: ArrayList<ArrayList<String>>

    public init(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>) {
        this.BOARD_SIZE = BOARD_SIZE
        this.ICONS = ICONS
        this.board = create_board(BOARD_SIZE, ICONS)
    }

    public static func create_board(BOARD_SIZE: ArrayList<Int64>, ICONS: ArrayList<String>): ArrayList<ArrayList<String>> {
        let rows: Int64 = BOARD_SIZE.get(0)
        let cols: Int64 = BOARD_SIZE.get(1)
        let board: ArrayList<ArrayList<String>> = ArrayList()
        let rand: Random = Random()
        for (let i: Int64 = 0; i < rows; i++) {
            let row: ArrayList<String> = ArrayList()
            for (let j: Int64 = 0; j < cols; j++) {
                row.add(ICONS.get(rand.int_range(0, ICONS.size())))
            }
            board.add(row)
        }
        return board
    }

    public func is_valid_move(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        if (pos1 == pos2) {
            return false
        }
        if (pos1.get(0) < 0 || pos1.get(0) >= BOARD_SIZE.get(0) || pos1.get(1) < 0 || pos1.get(1) >= BOARD_SIZE.get(1)) {
            return false
        }
        if (pos2.get(0) < 0 || pos2.get(0) >= BOARD_SIZE.get(0) || pos2.get(1) < 0 || pos2.get(1) >= BOARD_SIZE.get(1)) {
            return false
        }
        if (board.get(pos1.get(0)).get(pos1.get(1)) != board.get(pos2.get(0)).get(pos2.get(1))) {
            return false
        }
        return has_path(pos1, pos2)
    }

    public func has_path(pos1: (Int64, Int64), pos2: (Int64, Int64)): Bool {
        let visited: ArrayList<(Int64, Int64)> = ArrayList()
        return dfs(pos1, pos2, visited, 0)
    }

    private func dfs(current: (Int64, Int64), target: (Int64, Int64), visited: ArrayList<(Int64, Int64)>, turns: Int64): Bool {
        if (current == target) {
            return true
        }
        if (turns > 2) {
            return false
        }
        visited.add(current)
        let directions: ArrayList<(Int64, Int64)> = ArrayList([(-1, 0), (1, 0), (0, -1), (0, 1)])
        for (dir in directions) {
            let new_x: Int64 = current.get(0) + dir.get(0)
            let new_y: Int64 = current.get(1) + dir.get(1)
            while (new_x >= 0 && new_x < BOARD_SIZE.get(0) && new_y >= 0 && new_y < BOARD_SIZE.get(1)) {
                let new_pos: (Int64, Int64) = (new_x, new_y)
                if (new_pos == target) {
                    return true
                }
                if (board.get(new_x).get(new_y) != ' ' && !contains(visited, new_pos)) {
                    break
                }
                if (dfs(new_pos, target, visited.clone(), turns + (dir != directions.get(0) ? 1 : 0))) {
                    return true
                }
                new_x += dir.get(0)
                new_y += dir.get(1)
            }
        }
        return false
    }

    public static func contains(visited: ArrayList<(Int64, Int64)>, pos: (Int64, Int64)): Bool {
        for (v in visited) {
            if (v == pos) {
                return true
            }
        }
        return false
    }

    public func remove_icons(pos1: (Int64, Int64), pos2: (Int64, Int64)): Unit {
        board.get(pos1.get(0)).set(pos1.get(1), ' ')
        board.get(pos2.get(0)).set(pos2.get(1), ' ')
    }

    public func is_game_over(): Bool {
        for (row in board) {
            for (cell in row) {
                if (cell != ' ') {
                    return false
                }
            }
        }
        return true
    }
}

class Manacher {

    let input_string: String

    public init(input_string: String) {
        this.input_string = input_string
    }

    public func palindromic_length(center: Int64, diff: Int64, string: String): Int64 {
        if ((center - diff) >= 0) and ((center + diff) < string.count) and (string[center - diff] == string[center + diff]) {
            return 1 + palindromic_length(center: center, diff: diff + 1, string: string)
        } else {
            return 0
        }
    }

    public func palindromic_string(): String {
        let max_length = input_string.count
        if max_length == 0 {
            return ""
        }
        let new_string = input_string.map { String($0) }.joined(separator: "|")
        let new_length = new_string.count
        var max_palindrome = 1
        var start = 0
        var end = 0
        for i in 0..<new_length {
            let length = palindromic_length(center: Int64(i), diff: 1, string: new_string)
            if length > max_palindrome {
                max_palindrome = Int(length)
                start = i - max_palindrome
                end = i + max_palindrome
            }
        }
        let result = new_string[start...end].replacingOccurrences(of: "|", with: "")
        return result
    }
}

import std.collection.ArrayList
import std.math.abs

class MetricsCalculator {

    var true_positives: Int64
    var false_positives: Int64
    var false_negatives: Int64
    var true_negatives: Int64

    public init() {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0
    }

    public func update(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Unit {
        this.true_positives = 0
        this.false_positives = 0
        this.false_negatives = 0
        this.true_negatives = 0

        for i in 0..predicted_labels.size() {
            val predicted = predicted_labels.get(i)
            val true_label = true_labels.get(i)

            if (predicted == 1 && true_label == 1) {
                this.true_positives += 1
            } else if (predicted == 1 && true_label == 0) {
                this.false_positives += 1
            } else if (predicted == 0 && true_label == 1) {
                this.false_negatives += 1
            } else {
                this.true_negatives += 1
            }
        }
    }

    public func precision(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        val total_positives = this.true_positives + this.false_positives
        return if (total_positives == 0) 0.0 else this.true_positives.toFloat64() / total_positives.toFloat64()
    }

    public func recall(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        val total_true_positives = this.true_positives + this.false_negatives
        return if (total_true_positives == 0) 0.0 else this.true_positives.toFloat64() / total_true_positives.toFloat64()
    }

    public func f1_score(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        val p = this.precision(predicted_labels, true_labels)
        val r = this.recall(predicted_labels, true_labels)
        return if (p + r == 0.0) 0.0 else 2 * (p * r) / (p + r)
    }

    public func accuracy(predicted_labels: ArrayList<Int64>, true_labels: ArrayList<Int64>): Float64 {
        this.update(predicted_labels, true_labels)
        val total_samples = this.true_positives + this.false_positives + this.false_negatives + this.true_negatives
        return if (total_samples == 0) 0.0 else (this.true_positives + this.true_negatives).toFloat64() / total_samples.toFloat64()
    }
}

