    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<Float64>()
        let mrr_sum = if data is ArrayList {
            let (actual_list, ground_truth_num) = data as (ArrayList<Int64>, Int64)
            let rank = actual_list.index_of(1) + 1
            let reciprocal_rank = 1.0 / rank.to_float64()
            results.add(reciprocal_rank)
            reciprocal_rank
        } else {
            let mut sum = 0.0
            for (actual_list, ground_truth_num) in data as ArrayList<(ArrayList<Int64>, Int64)> {
                let rank = actual_list.index_of(1) + 1
                let reciprocal_rank = 1.0 / rank.to_float64()
                results.add(reciprocal_rank)
                sum += reciprocal_rank
            }
            sum / data.size().to_float64()
        }
        (mrr_sum, results)
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<Float64>()
        let map_sum = if data is ArrayList {
            let (actual_list, ground_truth_num) = data as (ArrayList<Int64>, Int64)
            let mut sum_ap = 0.0
            let mut correct_count = 0
            for (i, val) in actual_list.enumerate() {
                if val == 1 {
                    correct_count += 1
                    sum_ap += correct_count.to_float64() / (i + 1).to_float64()
                }
            }
            let ap = sum_ap / ground_truth_num.to_float64()
            results.add(ap)
