class MusicPlayer {

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        this.playlist.remove(song)
    }

    public func play(): Option<String> {
        if this.playlist.is_empty() {
            return None
        }
        if this.current_song == None {
            this.current_song = this.playlist.get(0)
        }
        return this.current_song
    }

    public func stop(): Bool {
        if this.current_song != None {
            this.current_song = None
            return true
        }
        return false
    }

    public func switch_song(): Bool {
        if this.playlist.is_empty() || this.current_song == None {
            return false
        }
        val index = this.playlist.index_of(this.current_song.unwrap())
        if index + 1 < this.playlist.size() {
            this.current_song = this.playlist.get(index + 1)
            return true
        }
        return false
    }

    public func previous_song(): Bool {
        if this.playlist.is_empty() || this.current_song == None {
            return false
        }
        val index = this.playlist.index_of(this.current_song.unwrap())
        if index - 1 >= 0 {
            this.current_song = this.playlist.get(index - 1)
            return true
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        if volume >= 0 && volume <= 100 {
            this.volume = volume
            return true
        }
        return false
    }

    public func shuffle(): Bool {
        if this.playlist.is_empty() {
            return false
        }
        Random.shuffle(this.playlist)
        return true
    }
}

