import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN",
                            "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match x {
            case Some(val) => return this.format_string(val)
            case None => return ""
        }
    }

    public func format_string(x: String): String {
        let parts = x.split("\\.")
        let integer_part = parts[0]
        let decimal_part = if parts.len() > 1 { parts[1] } else { "" }

        let integer_words = this.parse_integer(integer_part)
        let decimal_words = if decimal_part != "" { " POINT " + this.parse_decimal(decimal_part) } else { "" }

        let result = integer_words + decimal_words
        return if result != "" { result + " ONLY" } else { "" }
    }

    private func parse_integer(s: String): String {
        let s = s.trim_start('0')
        if s == "" { return "ZERO" }

        let len = s.len()
        let mut result = ""
        let mut i = 0
        let mut more_index = 0

        while i < len {
            let start = if len - i - 3 >= 0 { len - i - 3 } else { 0 }
            let end = len - i
            let chunk = s.slice(start, end)

            let chunk_words = this.trans_three(chunk)
            if chunk_words != "" {
                let more = this.parse_more(more_index)
                result = if result != "" { chunk_words + " " + more + " " + result } else { chunk_words + " " + more }
            }

            i += 3
            more_index += 1
        }

        return result.trim()
    }

    private func parse_decimal(s: String): String {
        let mut result = ""
        for c in s.chars() {
            let digit = c.to_string().to_i32()
            result += this.NUMBER[digit] + " "
        }
        return result.trim()
    }

    public func trans_two(s: String): String {
        let n = s.to_i32()
        if n < 10 { return this.NUMBER[n] }
        if n < 20 { return this.NUMBER_TEEN[n - 10] }

        let ten = n / 10
        let unit = n % 10
        return if unit != 0 { this.NUMBER_TEN[ten - 1] + " " + this.NUMBER[unit] } else { this.NUMBER_TEN[ten - 1] }
    }

    public func trans_three(s: String): String {
        let s = s.trim_start('0')
        if s == "" { return "" }

        let n = s.to_i32()
        let len = s.len()

        if len == 1 { return this.NUMBER[n] }
        if len == 2 { return this.trans_two(s) }

        let hundred = n / 100
        let remainder = n % 100

        let hundred_part = this.NUMBER[hundred] + " HUNDRED"
        let remainder_part = if remainder != 0 { " AND " + this.trans_two(remainder.to_string()) } else { "" }

        return hundred_part + remainder_part
    }

    public func parse_more(i: Int64): String {
        if i < this.NUMBER_MORE.len() { return this.NUMBER_MORE[i] }
        return ""
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let chars = string.runes()
        let result = ArrayList[Rune]()
        let len = chars.size()
        var i = 0

        while i < len {
            let current = chars[i]
            if current == '&' && i + 1 < len && chars[i + 1] == '#' {
                i += 2
                var is_hex = false
                if i < len && chars[i] == 'x' {
                    is_hex = true
                    i += 1
                }

                let start = i
                while i < len && (chars[i].is_digit() || (is_hex && NumericEntityUnescaper.is_hex_char(chars[i]))) {
                    i += 1
                }

                if i < len && chars[i] == ';' {
                    let entity = chars.sub_list(start, i).to_string()
                    i += 1

                    let num: Int?
                    if is_hex {
                        num = RadixConvertible.to_int(entity, 16)
                    } else {
                        num = RadixConvertible.to_int(entity, 10)
                    }

                    if let num = num {
                        result.push(Rune(num))
                        continue
                    }
                }

                i = start - (if is_hex { 3 } else { 2 })
                result.push('&')
                result.push('#')
                if is_hex {
                    result.push('x')
                }
            } else {
                result.push(current)
                i += 1
            }
        }

        return result.to_string()
    }

    public static func is_hex_char(char: Rune): Bool {
        return char >= '0' && char <= '9' || char >= 'a' && char <= 'f' || char >= 'A' && char <= 'F'
    }
}

