import std.collection.ArrayList

class PushBoxGame {

    let map: ArrayList<ArrayList<String>>
    var player_row: Int64
    var player_col: Int64
    let targets: ArrayList<ArrayList<Int64>>
    let boxes: ArrayList<ArrayList<Int64>>
    var target_count: Int64
    var is_game_over: Bool

    public init(map: ArrayList<ArrayList<String>>) {
        this.map = map
        this.player_row = 0
        this.player_col = 0
        this.targets = ArrayList<ArrayList<Int64>>()
        this.boxes = ArrayList<ArrayList<Int64>>()
        this.target_count = 0
        this.is_game_over = false

        func init_game() {
            for i in 0..<map.size() {
                for j in 0..<map[i].size() {
                    if map[i][j] == "O" {
                        player_row = i
                        player_col = j
                    } elif map[i][j] == "G" {
                        targets.add(ArrayList<Int64>([i, j]))
                        target_count += 1
                    } elif map[i][j] == "X" {
                        boxes.add(ArrayList<Int64>([i, j]))
                    }
                }
            }
        }
        init_game()
    }

    public func check_win(): Bool {
        var boxes_on_target = 0
        for box in boxes {
            for target in targets {
                if box[0] == target[0] and box[1] == target[1] {
                    boxes_on_target += 1
                    break
                }
            }
        }
        this.is_game_over = boxes_on_target == target_count
        return this.is_game_over
    }

    public func move(direction: String): Bool {
        var new_row = player_row
        var new_col = player_col

        if direction == "w" {
            new_row -= 1
        } elif direction == "s" {
            new_row += 1
        } elif direction == "a" {
            new_col -= 1
        } elif direction == "d" {
            new_col += 1
        } else {
            return false
        }

        if map[new_row][new_col] == "#" {
            return false
        }

        var box_moved = false
        var box_index: Int64 = -1
        for i in 0..<boxes.size() {
            if boxes[i][0] == new_row and boxes[i][1] == new_col {
                box_index = i
                break
            }
        }

        if box_index != -1 {
            var box_new_row = new_row
            var box_new_col = new_col
            if direction == "w" {
                box_new_row -= 1
            } elif direction == "s" {
                box_new_row += 1
            } elif direction == "a" {
                box_new_col -= 1
            } elif direction == "d" {
                box_new_col += 1
            }

            if map[box_new_row][box_new_col] == "#" {
                return false
            }

            for box in boxes {
                if box[0] == box_new_row and box[1] == box_new_col {
                    return false
                }
            }

            boxes[box_index][0] = box_new_row
            boxes[box_index][1] = box_new_col
            box_moved = true
        }

        player_row = new_row
        player_col = new_col

        return check_win()
    }
}

import std.regex.Regex
import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        Regex regex = new Regex(pattern)
        return regex.match(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        Regex regex = new Regex(pattern)
        MatchIterator matches = regex.find_all(text)
        ArrayList<String> result = new ArrayList<String>()
        foreach (Match match : matches) {
            result.add(match.group(0))
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        Regex regex = new Regex(pattern)
        ArrayList<String> parts = regex.split(text)
        return parts
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        Regex regex = new Regex(pattern)
        return regex.replace(text, replacement)
    }

    public func generate_email_pattern(): String {
        return #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        return #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        return #'[.!?][\s]{1,2}(?=[A-Z])'#
    }

    public func split_sentences(text: String): ArrayList<String> {
        Regex regex = new Regex(generate_split_sentences_pattern())
        ArrayList<String> parts = regex.split(text)
        ArrayList<String> result = new ArrayList<String>()
        foreach (String part : parts) {
            result.add(part.trim())
        }
