class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions.get(0)
        let new_head = ArrayList<Int64>([head.get(0) + direction.get(0) * this.BLOCK_SIZE, head.get(1) + direction.get(1) * this.BLOCK_SIZE])
        this.positions.insert(0, new_head)
        if new_head.get(0) == this.food_position.get(0) && new_head.get(1) == this.food_position.get(1) {
            this.eat_food()
        } else {
            this.positions.remove(this.positions.size() - 1)
        }
        for i in 1..this.positions.size() {
            if new_head.get(0) == this.positions.get(i).get(0) && new_head.get(1) == this.positions.get(i).get(1) {
                this.reset()
                break
            }
        }
    }

    public func random_food_position(): Unit {
        let random = Random()
        var new_food_position: ArrayList<Int64>
        loop {
            new_food_position = ArrayList<Int64>([
                random.next_int(this.SCREEN_WIDTH / this.BLOCK_SIZE) * this.BLOCK_SIZE,
                random.next_int(this.SCREEN_HEIGHT / this.BLOCK_SIZE) * this.BLOCK_SIZE
            ])
            var collision = false
            for pos in this.positions {
                if pos.get(0) == new_food_position.get(0) && pos.get(1) == new_food_position.get(1) {
                    collision = true
                    break
                }
            }
            if not collision {
                break
            }
        }
        this.food_position = new_food_position
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length += 1
        this.score += 100
        this.random_food_position()
    }
}

import std.collection.ArrayList
import std.regex.Regex
import std.unicode.UnicodeStringExtension

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let sentences = ArrayList<String>()
        let pattern = Regex("(?<!Mr|Mrs|Dr)\\.\\s|\\?\\s")
        let matches = pattern.findAll(sentences_string)
        let start = 0

        for match in matches {
            let end = match.end()
            let sentence = sentences_string.substring(start, end - 1)
            sentences.add(sentence)
            start = end
        }

        if start < sentences_string.length() {
            sentences.add(sentences_string.substring(start))
        }

        return sentences
    }

    public func count_words(sentence: String): Int64 {
        let words = sentence.split(" ")
        let word_pattern = Regex("[a-zA-Z]+")
        let count = 0

        for word in words {
            if word_pattern.matches(word) {
                count += 1
            }
        }

        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        let max_count = 0

        for sentence in sentences {
            let current_count = count_words(sentence)
            if current_count > max_count {
                max_count = current_count
            }
        }

        return max_count
    }
}

