import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        sort(data)
        let length = data.size()
        if length % 2 == 1 {
            return data[length // 2].toFloat64()
        } else {
            return (data[length // 2 - 1].toFloat64() + data[length // 2].toFloat64()) / 2.0
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        let frequency = HashMap<Int64, Int64>()
        let max_freq = 0.toInt64()
        let modes = ArrayList<Int64>()

        for num in data {
            if frequency.containsKey(num) {
                frequency[num] = frequency[num] + 1
            } else {
                frequency.put(num, 1)
            }
            if frequency[num] > max_freq {
                max_freq = frequency[num]
            }
        }

        for (num, count) in frequency {
            if count == max_freq {
                modes.add(num)
            }
        }

        sort(modes)
        return modes
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if x.size() != y.size() or x.size() == 0 {
            return Option.none()
        }

        let x_mean = mean(x)
        let y_mean = mean(y)

        if x_mean.isEmpty() or y_mean.isEmpty() {
            return Option.none()
        }

        let x_mean_val = x_mean.get()
        let y_mean_val = y_mean.get()

        let xy_covariance = 0.0
        let x_variance = 0.0
        let y_variance = 0.0

        for i in 0..x.size() {
            let x_diff = x[i].toFloat64() - x_mean_val
            let y_diff = y[i].toFloat64() - y_mean_val
            xy_covariance += x_diff * y_diff
            x_variance += x_diff * x_diff
            y_variance += y_diff * y_diff
        }

        if x_variance == 0.0 or y_variance == 0.0 {
            return Option.none()
        }

        let corr = xy_covariance / sqrt(x_variance * y_variance)
        return Option.some(corr)
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if data.size() == 0 {
            return Option.none()
        }

        let sum = 0.toFloat64()
        for num in data {
            sum += num.toFloat64()
        }
        return Option.some(sum / data.size().toFloat64())
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        let matrix = ArrayList<ArrayList<Float64>>()

        for i in 0..data.size() {
            let row = ArrayList<Float64>()
            for j in 0..data.size() {
                let corr = correlation(data[i], data[j])
                if corr.isEmpty() {
                    row.add(0.0)
                } else {
                    row.add(corr.get())
                }
            }
            matrix.add(row)
        }

        return matrix
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let m = mean(data)
        if m.isEmpty() or data.size() == 0 {
            return Option.none()
        }

        let mean_val = m.get()
        let sum_sq_diff = 0.0

        for num in data {
            sum_sq_diff += (num.toFloat64() - mean_val) * (num.toFloat64() - mean_val)
        }

        let variance = sum_sq_diff / data.size().toFloat64()
        return Option.some(sqrt(variance))
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let m = mean(data)
        let sd = standard_deviation(data)

        if m.isEmpty() or sd.isEmpty() or sd.get() == 0.0 {
            return Option.none()
        }

        let mean_val = m.get()
        let sd_val = sd.get()
        let z_scores = ArrayList<Float64>()

        for num in data {
            z_scores.add((num.toFloat64() - mean_val) / sd_val)
        }

        return Option.some(z_scores)
    }
}

