class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        let index = this.portfolio.index_of(stock)
        if index >= 0 {
            this.portfolio.remove_at(index)
            return true
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let total_cost = stock.price * Float64(stock.quantity)
        if this.cash_balance >= total_cost {
            this.cash_balance -= total_cost
            this.portfolio.add(stock)
            return true
        }
        return false
    }

    public func sell_stock(stock: Stock): Bool {
        let index = this.portfolio.index_of(stock)
        if index >= 0 && this.portfolio[index].quantity >= stock.quantity {
            let sold_stock = this.portfolio[index]
            this.cash_balance += sold_stock.price * Float64(stock.quantity)
            sold_stock.quantity -= stock.quantity
            if sold_stock.quantity == 0 {
                this.portfolio.remove_at(index)
            }
            return true
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var total_value = this.cash_balance
        for stock in this.portfolio {
            total_value += stock.price * Float64(stock.quantity)
        }
        return total_value
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        var stock_summaries = ArrayList<HashMap<String, Any>>()
        var portfolio_value = this.cash_balance
        for stock in this.portfolio {
            let stock_value = stock.price * Float64(stock.quantity)
            portfolio_value += stock_value
            let summary = HashMap<String, Any>()
            summary.put("name", stock.name)
            summary.put("value", stock_value)
            stock_summaries.add(summary)
        }
        return (portfolio_value, stock_summaries)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * Float64(stock.quantity)
    }
}

import std.math.abs

class Thermostat {

    var current_temperature: Float64
    var target_temperature: Float64
    var mode: String

    public init(current_temperature: Float64, target_temperature: Float64, mode: String) {
        this.current_temperature = current_temperature
        this.target_temperature = target_temperature
        this.mode = mode
    }

    public func get_target_temperature(): Float64 {
        return this.target_temperature
    }

    public func set_target_temperature(temperature: Float64): Unit {
        this.target_temperature = temperature
    }

    public func get_mode(): String {
        return this.mode
    }

    public func set_mode(mode: String): Bool {
        if mode == "heat" or mode == "cool" {
            this.mode = mode
            return true
        }
        return false
    }

    public func auto_set_mode(): Unit {
        if this.current_temperature < this.target_temperature {
            this.mode = "heat"
        } else {
            this.mode = "cool"
        }
    }

    public func auto_check_conflict(): Bool {
        if (this.current_temperature < this.target_temperature and this.mode == "cool") or (this.current_temperature > this.target_temperature and this.mode == "heat") {
            this.auto_set_mode()
            return false
        }
        return true
    }

    public func simulate_operation(): Int64 {
        this.auto_set_mode()
        var time: Int64 = 0
        while abs(this.current_temperature - this.target_temperature) > 0.1 {
            if this.mode == "heat" {
                this.current_temperature += 0.1
            } else {
                this.current_temperature -= 0.1
            }
            time += 1
        }
        return time
    }
}

import std.collection.ArrayList

class TicTacToe {

    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(N!: Int64 = 3) {
        this.board = ArrayList<ArrayList<String>>()
        for (_ in 0..3) {
            let row = ArrayList<String>()
            for (_ in 0..N) {
                row.add(' ')
            }
            this.board.add(row)
        }
        this.current_player = 'X'
    }

    public func make_move(row: Int64, col: Int64): Bool {
        if row >= 3 || col >= 3 || row < 0 || col < 0 {
            return false
        }
        if this.board.get(row).get(col) != ' ' {
            return false
        }
        this.board.get(row).set(col, this.current_player)
        this.current_player = if this.current_player == 'X' then 'O' else 'X'
        return true
    }

    public func check_winner(): Option<String> {
        for i in 0..3 {
            if this.board.get(i).get(0) != ' ' && this.board.get(i).get(0) == this.board.get(i).get(1) && this.board.get(i).get(1) == this.board.get(i).get(2) {
                return Option.Some(this.board.get(i).get(0))
            }
            if this.board.get(0).get(i) != ' ' && this.board.get(0).get(i) == this.board.get(1).get(i) && this.board.get(1).get(i) == this.board.get(2).get(i) {
                return Option.Some(this.board.get(0).get(i))
            }
        }
        if this.board.get(0).get(0) != ' ' && this.board.get(0).get(0) == this.board.get(1).get(1) && this.board.get(1).get(1) == this.board.get(2).get(2) {
            return Option.Some(this.board.get(0).get(0))
        }
        if this.board.get(0).get(2) != ' ' && this.board.get(0).get(2) == this.board.get(1).get(1) && this.board.get(1).get(1) == this.board.get(2).get(0) {
            return Option.Some(this.board.get(0).get(2))
        }
        return Option.None()
    }

    public func is_board_full(): Bool {
        for row in this.board {
            for cell in row {
                if cell == ' ' {
                    return false
                }
            }
        }
        return true
    }
}

