import std.math.numeric.Decimal
import std.math.numeric.round
import std.math.abs

class TriCalculator {

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let radians = x * PI / 180.0
        return self.taylor(x, 50)
    }

    public func factorial(a: Int64): Decimal {
        if a <= 1 {
            return Decimal(1)
        }
        return Decimal(a) * self.factorial(a - 1)
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        let radians = x * PI / 180.0
        var result: Float64 = 0.0
        for i in 0..n {
            let term = pow(-1.0, Float64(i)) * pow(radians, Float64(2 * i)) / Float64(self.factorial(2 * i))
            result += term
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let radians = x * PI / 180.0
        var result: Float64 = 0.0
        for i in 0..50 {
            let term = pow(-1.0, Float64(i)) * pow(radians, Float64(2 * i + 1)) / Float64(self.factorial(2 * i + 1))
            result += term
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = self.cos(x)
        if abs(cos_val) < 0.000001 {
            return Option.none()
        }
        return Option.some(self.sin(x) / cos_val)
    }
}

