import std.convert.Parsable

class Parser {

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception "Unexpected end of expression"
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        let random = Random()
        this.nums.clear()
        for (var i = 0; i < 4; i += 1) {
            this.nums.add(random.nextInt(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        let used_nums = ArrayList<Int64>()
        for (num in this.nums) {
            used_nums.add(num)
        }
        let expr_nums = ArrayList<Int64>()
        var current_num = ""
        for (ch in expression) {
            if (ch.isAsciiDigit()) {
                current_num += ch.toString()
            } else {
                if (current_num != "") {
                    expr_nums.add(Int64.parse(current_num))
                    current_num = ""
                }
            }
        }
        if (current_num != "") {
            expr_nums.add(Int64.parse(current_num))
        }
        if (expr_nums.size != used_nums.size) {
            return false
        }
        expr_nums.sort()
        used_nums.sort()
        if (expr_nums != used_nums) {
            return false
        }
        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        let parser = Parser(expression)
        let result = parser.parse()
        return result == 24
    }
}

import std.collection.HashMap

class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        match this.url.split("://") {
            [scheme, ..._] => Some(scheme),
            _ => None,
        }
    }

    public func get_host(): Option<String> {
        match this.url.split("://") {
            [_, rest] => match rest.split("/") {
                [host, ..._] => Some(host),
                _ => None,
            },
            _ => None,
        }
    }

    public func get_path(): Option<String> {
        match this.url.split("://") {
            [_, rest] => match rest.splitn("/", 2) {
                [_, path] => Some("/" + path),
                _ => Some("/"),
            },
            _ => None,
        }
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        match this.url.split("?") {
            [_, query] => {
                let parts = query.split("#")[0]
                let param_pairs = parts.split("&")
                let mut params = HashMap::new()
                for pair in param_pairs {
                    match pair.split("=") {
                        [key, value] => params.insert(key, value),
                        [key] => params.insert(key, ""),
                        _ => continue,
                    }
                }
                Some(params)
            },
            _ => None,
        }
    }

    public func get_fragment(): Option<String> {
        match this.url.split("#") {
            [_, fragment] => Some(fragment),
            _ => None,
        }
    }
}

import std.collection.ArrayList

class UrlPath {

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        let fixed_path = UrlPath.fix_path(path)
        let parts = fixed_path.split('/')
        for part in parts {
            if not part.is_empty() {
                this.segments.add(part)
            }
        }
        this.with_end_tag = path.ends_with('/')
    }

    public static func fix_path(path: String): String {
        let mut trimmed = path.trim()
        while trimmed.starts_with('/') {
            trimmed = trimmed.substring(1)
        }
        while trimmed.ends_with('/') {
            trimmed = trimmed.substring(0, trimmed.length() - 1)
        }
        return trimmed
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        require(vector_1.size() == vector_2.size(), "Vectors must be of same size.")
        let dot_product = VectorUtil.dot(vector_1, vector_2)
        let norm_1 = VectorUtil.norm(vector_1)
        let norm_2 = VectorUtil.norm(vector_2)
        return dot_product / (norm_1 * norm_2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let similarities = ArrayList<Float64>()
        for other_vector in vectors_all {
            similarities.add(VectorUtil.similarity(vector_1, other_vector))
        }
        return similarities
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let avg_1 = VectorUtil.average(vector_list__one)
        let avg_2 = VectorUtil.average(vector_list_two)
        return VectorUtil.similarity(avg_1, avg_2)
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let idf_dict = HashMap<String, Float64>()
        for (key, count) in number_dict {
            let weight = log((total_num + 1.0) / (count + 1.0))
            idf_dict.put(key, weight)
        }
        return idf_dict
    }

    private static func dot(v1: ArrayList<Float64>, v2: ArrayList<Float64>): Float64 {
        require(v1.size() == v2.size(), "Vectors must be of same size.")
        var sum = 0.0
        for i in 0..v1.size() {
            sum += v1.get(i) * v2.get(i)
        }
        return sum
    }

    private static func norm(vector: ArrayList<Float64>): Float64 {
        var sum_sq = 0.0
        for value in vector {
            sum_sq += pow(value, 2.0)
        }
        return sqrt(sum_sq)
    }

    private static func average(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        require(vectors.size() > 0, "Cannot average empty vector list.")
        let dim = vectors.get(0).size()
        let avg = ArrayList<Float64>(size=dim, fill=0.0)
        for vector in vectors {
            for i in 0..dim {
                avg.set(i, avg.get(i) + vector.get(i))
            }
        }
        for i in 0..dim {
            avg.set(i, avg.get(i) / vectors.size())
        }
        return avg
    }
}

