class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        if this.inventory.contains_key(product_id) {
            let existing_product = this.inventory.get(product_id).unwrap()
            existing_product.quantity += quantity
        } else {
            this.inventory.put(product_id, Product(name, quantity))
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        if this.inventory.contains_key(product_id) {
            let existing_product = this.inventory.get(product_id).unwrap()
            existing_product.quantity += quantity
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        if this.inventory.contains_key(product_id) {
            return Option.some(this.inventory.get(product_id).unwrap().quantity)
        } else {
            return Option.none()
        }
    }

    public func create_order(order_id: Int64, product_id: Int64,quantity: Int64): Bool {
        if !this.inventory.contains_key(product_id) {
            return false
        }
        let product = this.inventory.get(product_id).unwrap()
        if product.quantity < quantity {
            return false
        }
        product.quantity -= quantity
        this.orders.put(order_id, Order(product_id, quantity, "Shipped"))
        return true
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        if !this.orders.contains_key(order_id) {
            return false
        }
        let order = this.orders.get(order_id).unwrap()
        order.status = status
        return true
    }

    public func track_order(order_id: Int64): Option<String> {
        if this.orders.contains_key(order_id) {
            return Option.some(this.orders.get(order_id).unwrap().status)
        } else {
            return Option.none()
        }
    }
}

